def _m10():
    from content.m07_m08 import SER
    ex = []
    e1, e2, e3, e4, e5 = {}, {}, {}, {}, {}
    for ds, (name, sql, key, task, measure, label, top) in V1.items():
        e1[ds] = dict(story='Analysts keep rewriting the same summary query.', task=task, cols=None, sql=sql,
                      pre='DROP VIEW IF EXISTS %s' % name, verify='SELECT * FROM %s ORDER BY %s' % (name, key))
        e2[ds] = dict(story='A manager wants a quick answer from the new view.', task='Using the %s view (it is created for you if missing), return %s. Return all of its columns, sorted by %s highest first, then %s.' % (name, top, measure, label),
                      cols=None, sql='SELECT *\nFROM %s\nORDER BY %s DESC, %s\nLIMIT 5;' % (name, measure, label), pre='DROP VIEW IF EXISTS %s;\n%s' % (name, sql))
    for ds, (name, sql, key, task) in V2.items():
        e3[ds] = dict(story='The team wants a ready-made labelled summary.', task=task, cols=None, sql=sql, pre='DROP VIEW IF EXISTS %s' % name, verify='SELECT * FROM %s ORDER BY %s' % (name, key))
    for ds, (name, val) in V3.items():
        cte, v, d, who, noun = SER[ds]
        body = cte.replace('\n    ', '\n')
        vsql = 'CREATE VIEW %s AS\n%s;' % (name, body)
        e4[ds] = dict(story='%s wants the monthly series available to everyone.' % who,
                      task='Create a view called %s with one row per month: month (YYYY-MM) and %s, where %s is %s. Do not round.' % (name, val, val, noun),
                      cols=None, sql=vsql, pre='DROP VIEW IF EXISTS %s' % name, verify='SELECT month, ROUND(%s, 2) AS %s FROM %s ORDER BY month' % (val, val, name))
        cname, csql, ckey, ctask, cmeasure, clabel, ctop = V1[ds]
        e5[ds] = dict(story='Reporting wants a second view built on top of the first.',
                      task='Building on the %s view (created for you if missing), create a view called %s_ranked that adds a column rank_overall: the DENSE_RANK of %s, highest = 1. It must keep every column of %s.' % (cname, cname, cmeasure, cname),
                      cols=None, sql='CREATE VIEW %s_ranked AS\nSELECT v.*,\n       DENSE_RANK() OVER (ORDER BY v.%s DESC) AS rank_overall\nFROM %s v;' % (cname, cmeasure, cname),
                      pre='DROP VIEW IF EXISTS %s_ranked;\nDROP VIEW IF EXISTS %s;\n%s' % (cname, cname, csql), verify='SELECT * FROM %s_ranked ORDER BY rank_overall, %s' % (cname, ckey))
    return e1, e2, e3, e4, e5


